SELECT p.id AS position_id, e.delivery_status, COUNT(*) AS n, MIN(e.price) AS min_price, MAX(e.price) AS max_price, MIN(e.observed_at) AS first_obs, MAX(e.observed_at) AS last_obs FROM paper_position p JOIN market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.opened_at - INTERVAL 15 SECOND AND p.closed_at + INTERVAL 5 SECOND WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, e.delivery_status ORDER BY p.id, e.delivery_status